  return (
    <div
      ref={containerRef}
      className={['dg-grid', stacked && 'dg-grid_stacked', drag && 'dg-grid_active'].filter(Boolean).join(' ')}
      style={stacked ? undefined : { height: Math.max(totalHeight, rowHeight) }}
    >
      {width > 0 && placeholder}
      {width > 0 && items}
    </div>
  );
}
