            <g
              key={b.seg.name}
              tabIndex={0}
              aria-label={`${b.seg.name}: ${b.text}`}
              onPointerEnter={() => setHover(b.i)}
              onPointerLeave={() => setHover(null)}
              onFocus={() => setHover(b.i)}
              onBlur={() => setHover(null)}
