                  {b.text}
                </text>
              )}
            </g>
          ))}
        </svg>
      )}
      {hovered && (
        <div className="viz-tooltip" style={{ left: hovered.x + hovered.w / 2, top: HEIGHT + 4 }} role="status">
          <div className="viz-tooltip__row">
            <span className="viz-key" style={{ background: hovered.seg.color }} aria-hidden="true" />
