          <Text variant="caption-2" color="secondary">
            к прошлому периоду
          </Text>
        </div>
        <div className="stat__spark">
          <Sparkline values={kpi.trend} width={hero ? 140 : 96} height={hero ? 36 : 28} />
        </div>
      </div>
    </WidgetFrame>
  );
}
