const PLANS = ['Start', 'Pro', 'Business', 'Enterprise'];

export function getDashboardData(range: Range): DashboardData {
  const days = RANGE_OPTIONS.find((option) => option.value === range)?.days ?? 30;
  const rand = mulberry32(1000 + days);

