              aria-label={theme === 'light' ? 'Включить тёмную тему' : 'Включить светлую тему'}
              title={theme === 'light' ? 'Тёмная тема' : 'Светлая тема'}
            >
              <Icon data={theme === 'light' ? MoonIcon : SunIcon} size={16} />
            </Button>
          </div>
        </header>

